// Classify escalation priority and determine notification dispatch
const body = $input.first().json.body || $input.first().json;

if (!body.escalation_id || !body.category) {
  throw new Error('escalation_id and category are required.');
}

const category = body.category;
let alertLevel = 'ROUTINE';
let recipientTeam = 'care_coordination';

if (category === 'emergency_related') {
  alertLevel = 'EMERGENCY_IMMEDIATE';
  recipientTeam = 'emergency_duty_clinician';
} else if (category === 'clinical_concern' || category === 'medication_concern') {
  alertLevel = 'HIGH_PRIORITY_CLINICAL';
  recipientTeam = 'nursing_staff';
} else if (category === 'human_request') {
  alertLevel = 'STAFF_CALLBACK_REQUEST';
  recipientTeam = 'care_coordinator';
}

return [{
  json: {
    escalation_id: body.escalation_id,
    client_id: body.client_id || 'unknown',
    category: category,
    alert_level: alertLevel,
    recipient_team: recipientTeam,
    reason: body.reason || 'Escalation triggered by AI Agent safety boundary',
    timestamp: new Date().toISOString()
  }
}];

// Prepare structured staff alert payload
const data = $input.first().json;
const alertPayload = {
  event: 'HUMAN_ESCALATION_TRIGGERED',
  alert_level: data.alert_level,
  recipient_team: data.recipient_team,
  escalation_id: data.escalation_id,
  category: data.category,
  reason: data.reason,
  action_required: data.alert_level === 'EMERGENCY_IMMEDIATE' 
    ? 'IMMEDIATE CLINICAL SAFETY PROTOCOL REQUIRED'
    : 'HUMAN REVIEW REQUIRED WITHIN PROGRAM TIMEFRAME',
  dispatched_at: data.timestamp
};

return [{
  json: alertPayload
}];

